static int gs_stdin(void *inst, char *buf, int len)
{
        size_t to_copy = min(len, g_size);
        to_copy = min(INT_MAX, to_copy);

        memcpy(buf, g_data, to_copy);

        g_data += to_copy;
        g_size -= to_copy;

        return to_copy;
}

